open Raster2.Render_ir
let ok=function Ok x->x|Error _->failwith"IR error"
let rect x y width height={x;y;width;height}
let stream()=ok(create[|Clear 0x11223344l;Push_clip(rect 0. 0. 64. 64.);Push_transform{xx=1.;xy=0.;yx=0.;yy=1.;tx=2.;ty=3.};Geometry{vertices=[|0.;0.;1.;0.;0.;1.|];indices=[|0;1;2|];color=0xff00ffffl};Geometry{vertices=[|2.;2.;3.;2.;2.;3.|];indices=[|0;1;2|];color=0xff00ffffl};Image{resource_id=7;source=rect 0. 0. 1. 1.;destination=rect 4. 5. 6. 7.};Glyphs{resource_id=9;color=0xffffffffl;glyphs=[|{glyph_id=65;x=1.;y=2.}|]};Pop_transform;Pop_clip|])
let ()=let value=stream()in let batches=batches value in assert(Array.length batches=8);assert(batches.(3).count=2);let copied=commands value in(match copied.(3)with Geometry g->g.vertices.(0)<-99.|_->assert false);assert(commands value<>copied);(match create[|Geometry{vertices=[|0.;0.|];indices=[|1;1;1|];color=0l}|]with Error(Invalid_index 1)->()|_->failwith"bad index");(match create[|Image{resource_id=0;source=rect 0. 0. 1. 1.;destination=rect 0. 0. 1. 1.}|]with Error(Invalid_resource_id 0)->()|_->failwith"bad resource");(match create[|Push_clip(rect 0. 0. 1. 1.)|]with Error Unbalanced_clip->()|_->failwith"unbalanced clip");(match create[|Push_transform{xx=nan;xy=0.;yx=0.;yy=1.;tx=0.;ty=0.};Pop_transform|]with Error Non_finite->()|_->failwith"NaN transform");let encoded=serialize value and digest=hash value in let workers=Array.init 4(fun _->Domain.spawn(fun()->let x=stream()in serialize x,hash x))in Array.iter(fun worker->let bytes,hash=Domain.join worker in assert(bytes=encoded&&hash=digest))workers;print_endline"Raster2 deterministic render IR passed"
